#!/usr/bin/env python3
"""analyze_frames.py — Analyze extracted frames with Claude Vision API."""

import argparse
import base64
import json
import os
import time
from pathlib import Path
from typing import List, Optional

try:
    import anthropic
except ImportError:
    anthropic = None


def encode_image(path: Path) -> str:
    """Base64-encode an image file."""
    with open(path, "rb") as f:
        return base64.b64encode(f.read()).decode("utf-8")


def load_prompt(mode: str) -> str:
    """Load system prompt for given analysis mode."""
    prompts = {
        "describe": "Describe what is happening in these video frames. Be concise but detailed.",
        "objects": "Identify all objects, UI elements, text, and entities visible in these frames. List them clearly.",
        "actions": "Describe human actions, behaviors, and operation sequences shown in these frames.",
        "academic": "Analyze these academic lecture frames. Extract slide content, method diagrams, experiment results, tables, and key claims. Be thorough.",
        "tutorial": "Analyze this technical tutorial. Extract step-by-step instructions, commands, and configurations shown.",
        "demo": "Analyze this product or system demo. List features demonstrated, UI flows, and key capabilities.",
        "meeting": "Summarize the key points, decisions, and action items from this meeting recording.",
    }
    return prompts.get(mode, prompts["describe"])


def build_messages(frames: List[Path], prompt: str, transcript_context: Optional[str] = None) -> List[dict]:
    """Build Claude messages with up to 4 frames as a mosaic."""
    content = []
    if transcript_context:
        content.append({
            "type": "text",
            "text": f"Transcript context:\n{transcript_context}\n\nNow analyze these frames:"
        })
    else:
        content.append({"type": "text", "text": prompt})

    for frame in frames:
        ext = frame.suffix.lower().replace(".", "")
        if ext == "jpg":
            ext = "jpeg"
        b64 = encode_image(frame)
        content.append({
            "type": "image",
            "source": {
                "type": "base64",
                "media_type": f"image/{ext}",
                "data": b64,
            }
        })

    return [{"role": "user", "content": content}]


def analyze_batch(client, frames: List[Path], prompt: str, transcript_context: Optional[str] = None, model: str = "claude-3-5-sonnet-20241022") -> str:
    """Send a batch of frames to Claude for analysis."""
    messages = build_messages(frames, prompt, transcript_context)
    response = client.messages.create(
        model=model,
        max_tokens=2048,
        messages=messages,
    )
    return response.content[0].text


def load_transcript(path: Optional[str]) -> Optional[str]:
    """Load transcript JSON and return concatenated text with timestamps."""
    if not path:
        return None
    p = Path(path)
    if not p.exists():
        return None
    data = json.loads(p.read_text())
    segments = data.get("segments", [])
    lines = []
    for seg in segments:
        lines.append(f"[{seg['start']:.1f}s - {seg['end']:.1f}s] {seg['text']}")
    return "\n".join(lines)


def get_transcript_slice(transcript: Optional[str], start_time: float, end_time: float) -> Optional[str]:
    """Extract transcript lines within a time window."""
    if not transcript:
        return None
    lines = []
    for line in transcript.splitlines():
        # Parse [start - end] text
        if line.startswith("[") and "s -" in line:
            try:
                parts = line[1:].split("s -", 1)
                t_start = float(parts[0])
                rest = parts[1]
                t_end = float(rest.split("s]", 1)[0])
                if t_start >= start_time and t_end <= end_time:
                    lines.append(line)
            except Exception:
                continue
    return "\n".join(lines) if lines else None


def main():
    parser = argparse.ArgumentParser(description="Analyze video frames with Claude Vision")
    parser.add_argument("--frames-dir", required=True, help="Directory containing extracted frames")
    parser.add_argument("--transcript", default=None, help="Optional transcript JSON path")
    parser.add_argument("--mode", default="describe", choices=["describe", "objects", "actions", "academic", "tutorial", "demo", "meeting"])
    parser.add_argument("--batch-size", type=int, default=4, help="Frames per API call")
    parser.add_argument("--out", required=True, help="Output JSON path")
    parser.add_argument("--model", default="claude-3-5-sonnet-20241022", help="Claude model name")
    parser.add_argument("--delay", type=float, default=1.0, help="Delay between API calls (seconds)")
    args = parser.parse_args()

    api_key = os.environ.get("ANTHROPIC_API_KEY")
    if not api_key:
        raise RuntimeError("ANTHROPIC_API_KEY environment variable not set")
    if anthropic is None:
        raise RuntimeError("anthropic SDK not installed. Run: pip install anthropic")

    client = anthropic.Anthropic(api_key=api_key)
    frames_dir = Path(args.frames_dir)
    frames = sorted(frames_dir.glob("*.jpg")) + sorted(frames_dir.glob("*.jpeg")) + sorted(frames_dir.glob("*.png"))
    if not frames:
        raise RuntimeError(f"No frames found in {frames_dir}")

    index_path = frames_dir / "index.json"
    index = json.loads(index_path.read_text()) if index_path.exists() else {}

    transcript = load_transcript(args.transcript)
    prompt = load_prompt(args.mode)

    results = []
    for i in range(0, len(frames), args.batch_size):
        batch = frames[i:i + args.batch_size]
        # Determine time window for this batch
        start_time = float("inf")
        end_time = float("-inf")
        for f in batch:
            t = index.get(f.name, 0)
            start_time = min(start_time, t)
            end_time = max(end_time, t)

        tx_slice = get_transcript_slice(transcript, start_time - 5, end_time + 5) if transcript else None

        print(f"Analyzing batch {i // args.batch_size + 1}/{(len(frames) - 1) // args.batch_size + 1}: {len(batch)} frames...")
        analysis = analyze_batch(client, batch, prompt, tx_slice, model=args.model)
        results.append({
            "frames": [f.name for f in batch],
            "start_time": round(start_time, 2) if start_time != float("inf") else None,
            "end_time": round(end_time, 2) if end_time != float("-inf") else None,
            "analysis": analysis,
        })
        if i + args.batch_size < len(frames):
            time.sleep(args.delay)

    with open(args.out, "w", encoding="utf-8") as f:
        json.dump({"mode": args.mode, "results": results}, f, indent=2, ensure_ascii=False)

    print(f"Analysis complete: {len(results)} batches written to {args.out}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""utils.py — Shared utilities for video analysis scripts."""

import json
import subprocess
from pathlib import Path


def run(cmd, check=True, capture=True):
    """Run a shell command."""
    kwargs = {"shell": True, "check": check}
    if capture:
        kwargs["capture_output"] = True
        kwargs["text"] = True
    return subprocess.run(cmd, **kwargs)


def load_json(path):
    """Load JSON file."""
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def save_json(data, path):
    """Save data to JSON file."""
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)


def ensure_dir(path):
    """Ensure directory exists."""
    Path(path).mkdir(parents=True, exist_ok=True)


def get_video_duration(path):
    """Get video duration in seconds via ffprobe."""
    cmd = f"ffprobe -v error -show_entries format=duration -of csv=p=0 '{path}'"
    result = run(cmd)
    return float(result.stdout.strip())


def format_timestamp(seconds):
    """Format seconds as HH:MM:SS."""
    m, s = divmod(int(seconds), 60)
    h, m = divmod(m, 60)
    return f"{h:02d}:{m:02d}:{s:02d}"
